import{_ as r,o as t,c as a,a6 as n}from"./chunks/framework.DHIwV8r3.js";const u=JSON.parse('{"title":"Our brand","description":"","frontmatter":{},"headers":[],"relativePath":"our-brand.md","filePath":"our-brand.md","lastUpdated":1794245099000}'),i={name:"our-brand.md"};function o(d,e,s,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="our-brand" tabindex="-1">Our brand <a class="header-anchor" href="#our-brand" aria-label="Permalink to &quot;Our brand&quot;">​</a></h1><p>We’re building a brand around <strong>plain white T-shirts</strong>. The audience, price, fit, name, and style are still open.</p><p>After competitor research, we’ll develop:</p><ol><li><strong>Customer persona:</strong> who we serve and what they need.</li><li><strong>Brand direction:</strong> positioning, offer, voice, and visual style.</li><li><strong>Website plan:</strong> shopping experience, content, and coding plan.</li></ol><p>Brand archetypes, Cialdini’s persuasion principles, and modern or postmodern design are ideas to explore—not decisions yet.</p><h2 id="designers-to-learn-from" tabindex="-1">Designers to learn from <a class="header-anchor" href="#designers-to-learn-from" aria-label="Permalink to &quot;Designers to learn from&quot;">​</a></h2><p>Open a designer’s page for a brief bio, portrait-source link, and a practical exercise. These are creative references, not a chosen direction or ranking.</p><table tabindex="0"><thead><tr><th>Designer</th><th>What we can learn</th><th>Example for our white tee</th></tr></thead><tbody><tr><td><a href="/white-tee-research/designers/jil-sander.html">Jil Sander</a></td><td>Make simplicity feel intentional through precision and material quality.</td><td>Show the neckline, fabric texture, and fit with clear photography and restrained typography.</td></tr><tr><td><a href="/white-tee-research/designers/christophe-lemaire.html">Christophe Lemaire</a>, working with Sarah-Linh Tran</td><td>Build around everyday use, movement, and proportions.</td><td>Show the tee worn alone and layered; explain its length, drape, and comfort in practical terms.</td></tr><tr><td><a href="/white-tee-research/designers/rei-kawakubo.html">Rei Kawakubo</a></td><td>Question conventions and create a distinctive point of view.</td><td>Test unexpected image crops or editorial layouts while keeping sizing, price, and checkout easy to find.</td></tr></tbody></table><p><strong>Starting point:</strong> study Sander and Lemaire for the product and everyday experience; use Kawakubo to explore a more experimental identity. Validate the direction through research before committing.</p><p><a href="/white-tee-research/research/brand-strategy.html">Compare competitors through archetypes and Cialdini’s principles</a>.</p>',10)])])}const m=r(i,[["render",o]]);export{u as __pageData,m as default};
